const V121_VERSION='1.2.1-dev';
const _brandCacheV121={};

async function brandDataUrlV121(path){
  if(_brandCacheV121[path])return _brandCacheV121[path];
  _brandCacheV121[path]=(async()=>{const res=await fetch(path);if(!res.ok)throw new Error('Não foi possível carregar a identidade visual.');const blob=await res.blob();return await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(blob)})})();
  return _brandCacheV121[path];
}
async function drawPdfBrandHeaderV121(pdf,title,subtitle=''){
  const icon=await brandDataUrlV121(BRAND_V120.icon);
  pdf.setFillColor(255,255,255);pdf.rect(0,0,210,50,'F');
  pdf.addImage(icon,'PNG',14,8,19,19);
  pdf.setTextColor(44,56,150);pdf.setFont('helvetica','bold');pdf.setFontSize(18);pdf.text(title,41,18);
  if(subtitle){pdf.setTextColor(92,99,120);pdf.setFont('helvetica','normal');pdf.setFontSize(9);pdf.text(pdf.splitTextToSize(subtitle,154),41,25)}
  pdf.setDrawColor(255,152,31);pdf.setLineWidth(1.4);pdf.line(14,46,196,46);pdf.setLineWidth(.2);
  return 54;
}
async function drawPdfContinuationHeaderV121(pdf,title){
  const icon=await brandDataUrlV121(BRAND_V120.icon);pdf.addImage(icon,'PNG',15,7,12,12);pdf.setTextColor(44,56,150);pdf.setFont('helvetica','bold');pdf.setFontSize(12);pdf.text(title,34,14);pdf.setDrawColor(255,152,31);pdf.line(15,21,195,21);return 27;
}
function applyBrandingV121(){
  const logo=document.querySelector('.brand-logo');if(logo)logo.innerHTML=`<img src="${BRAND_V120.icon}" alt="Símbolo Escola Piaget">`;
  const brandTitle=document.querySelector('.brand h1');if(brandTitle)brandTitle.textContent='Escola Piaget';
  const parentHero=document.querySelector('#parentScreen .parent-hero');if(parentHero){const old=parentHero.querySelector('img');if(old){old.src=BRAND_V120.icon;old.className='v121-parent-icon';old.removeAttribute('style')}}
}
