/* ---------- Caixa: cálculo, gestão consolidada e fechamento auditável ---------- */
function cashMovementEffectV121(m){const v=Number(m.valorCentavos||0),t=String(m.tipo||'');if(t==='venda'||t==='estorno_venda'||t==='transferencia_entrada'||t==='transferencia_entrada_cantina'||t==='ajuste_entrada')return v;if(['transferencia_saida','transferencia_saida_secretaria','suprimento_cantina','sangria','despesa','retirada','ajuste_saida','reembolso_venda'].includes(t))return-v;return 0}
function cashMetricsV121(cash,moves){const initial=Number(cash?.valorInicialCentavos||0),sales=(moves||[]).filter(x=>['venda','estorno_venda'].includes(x.tipo)).reduce((s,x)=>s+Number(x.valorCentavos||0),0),effects=(moves||[]).reduce((s,m)=>s+cashMovementEffectV121(m),0),expected=initial+effects;return{initial,sales,effects,expected,counted:cash?.valorContadoCentavos,diff:cash?.diferencaCentavos}}
async function cashRowsForDateV121(day){
  const cashDocs=await cashPagedDocsLegacyV221(db.collection('caixas').where('dataChave','==',day),100);
  const cashes=cashDocs.map(d=>({id:d.id,...d.data()}));const rows=await Promise.all(cashes.map(async cash=>{const moveDocs=await cashPagedDocsLegacyV221(db.collection('movimentos_caixa').where('caixaId','==',cash.id),250);const moves=moveDocs.map(d=>({id:d.id,...d.data()}));return{cash,moves,metrics:cashMetricsV121(cash,moves)}}));
  return rows.sort((a,b)=>`${a.cash.ponto}_${a.cash.turno}`.localeCompare(`${b.cash.ponto}_${b.cash.turno}`))
}
function cashPointLabelV121(p){return p==='cantina'?'Cantina':p==='secretaria'?'Secretaria':String(p||'-')}
