  y+=6;pdf.setTextColor(44,56,150);pdf.setFont('helvetica','bold');pdf.text('FECHAMENTO E RESPONSABILIDADE',15,y);y+=7;pdf.setTextColor(30);pdf.setFont('helvetica','normal');pdf.text(`Aberto por: ${c.operadorNome||c.operadorId||'-'}`,17,y);y+=5;pdf.text(`Assinatura operacional: ${c.fechadoPorNome||c.assinaturaOperacional?.nome||'-'}`,17,y);y+=5;pdf.text(`Fechado em: ${c.fechadoEm?humanDate(c.fechadoEm):'-'}`,17,y);y+=7;if(Number(c.diferencaCentavos||0)!==0){pdf.setFillColor(255,248,236);const just=pdf.splitTextToSize(`Justificativa da divergência: ${c.justificativaDivergencia||'Não informada'}`,172),h=just.length*4.5+8;pdf.roundedRect(15,y,180,h,2,2,'F');pdf.setTextColor(110,72,15);pdf.text(just,19,y+6);y+=h+7}
  pdf.setTextColor(44,56,150);pdf.setFont('helvetica','bold');pdf.text('MOVIMENTOS',15,y);y+=7;pdf.setTextColor(30);pdf.setFont('helvetica','normal');for(const m of [...(r.moves||[])].sort((a,b)=>String(a.criadoEm).localeCompare(String(b.criadoEm)))){if(y>274){pdf.addPage();y=await drawPdfContinuationHeaderV121(pdf,'Fechamento de caixa')}pdf.setFontSize(8.5);pdf.text(humanDate(m.criadoEm),15,y);pdf.text(pdf.splitTextToSize(String(m.tipo||'').replaceAll('_',' '),62),55,y);pdf.text(fmt(m.valorCentavos).replace(/\u00a0/g,' '),193,y,{align:'right'});y+=6}
