/* Relatório identifica a sessão para não misturar vários fechamentos do mesmo turno. */
window.downloadCashPdfV110=async function(){
  const r=state.currentCashReportV110;if(!r?.cash)return;const {jsPDF}=window.jspdf,pdf=new jsPDF({unit:'mm',format:'a4'}),c=r.cash,sessionTitle=c.numeroSessao?`${cashSessionLabelV123(c)} · `:'';let y=await drawPdfBrandHeaderV121(pdf,'Fechamento de caixa',`${sessionTitle}${cashPointLabelV121(r.point)} · ${cashShiftLabelV121(r.shift)} · ${c.dataChave||dateKey()}`);
  const lines=[['Saldo inicial',r.initial],['Vendas em dinheiro',r.sales],['Saldo esperado',c.valorEsperadoRegistradoCentavos??r.expected],['Saldo contado',c.valorContadoCentavos],['Diferença',c.diferencaCentavos]];pdf.setTextColor(30);pdf.setFontSize(10);for(const [label,val] of lines){if(val==null)continue;pdf.setDrawColor(225);pdf.line(15,y+6,195,y+6);pdf.setFont('helvetica','normal');pdf.text(label,17,y+4);pdf.setFont('helvetica','bold');pdf.text(fmt(val).replace(/0/g,' '),193,y+4,{align:'right'});y+=9}
  y+=6;pdf.setTextColor(44,56,150);pdf.setFont('helvetica','bold');pdf.text('FECHAMENTO E RESPONSABILIDADE',15,y);y+=7;pdf.setTextColor(30);pdf.setFont('helvetica','normal');if(c.numeroSessao){pdf.text(`Sessão: ${cashSessionLabelV123(c)}`,17,y);y+=5}pdf.text(`Aberto por: ${c.abertoPorNome||c.operadorNome||c.operadorId||'-'}`,17,y);y+=5;pdf.text(`Assinatura operacional: ${c.fechadoPorNome||c.assinaturaOperacional?.nome||'-'}`,17,y);y+=5;pdf.text(`Fechado em: ${c.fechadoEm?humanDate(c.fechadoEm):'-'}`,17,y);y+=7;if(Number(c.diferencaCentavos||0)!==0){pdf.setFillColor(255,248,236);const just=pdf.splitTextToSize(`Justificativa da divergência: ${c.justificativaDivergencia||'Não informada'}`,172),h=just.length*4.5+8;pdf.roundedRect(15,y,180,h,2,2,'F');pdf.setTextColor(110,72,15);pdf.text(just,19,y+6);y+=h+7}
  pdf.setTextColor(44,56,150);pdf.setFont('helvetica','bold');pdf.text('MOVIMENTOS',15,y);y+=7;pdf.setTextColor(30);pdf.setFont('helvetica','normal');for(const m of [...(r.moves||[])].sort((a,b)=>String(a.criadoEm).localeCompare(String(b.criadoEm)))){if(y>274){pdf.addPage();y=await drawPdfContinuationHeaderV121(pdf,'Fechamento de caixa')}pdf.setFontSize(8.5);pdf.text(humanDate(m.criadoEm),15,y);pdf.text(pdf.splitTextToSize(String(m.tipo||'').replaceAll('_',' '),62),55,y);pdf.text(fmt(m.valorCentavos).replace(/0/g,' '),193,y,{align:'right'});y+=6}
  const suffix=c.numeroSessao?`-sessao-${String(c.numeroSessao).padStart(3,'0')}`:'';pdf.save(`fechamento-caixa-${r.point}-${c.dataChave||dateKey()}${suffix}.pdf`)
};

